<script setup>
import {ref,watch,onUnmounted} from 'vue'
import {memberRpc} from './member-service.js'
import {formatMemberDate} from './member-table.js'
import MemberBulkControls from './MemberBulkControls.vue'
const props=defineProps({user:Object}),emit=defineEmits(['updated'])
const detail=ref(null),message=ref(''),answers=ref({}),memo=ref(''),reason=ref(''),busy=ref(false),requestCodes=ref([]),requestReason=ref('');let epoch=0
async function load(){const id=++epoch;detail.value=null;try{const data=await memberRpc('member_detail',{p_user:props.user.id});if(id!==epoch)return;detail.value=data;answers.value={...(data.answers||{})};memo.value=data.admin_memo||'';reason.value='';requestCodes.value=[...(data.requested_services||[])];requestReason.value=''}catch(e){if(id===epoch)message.value=e.message}}
function serviceName(c){return detail.value?.catalog.find(x=>x.id===c)?.name||c.replace('ai:prestige','AI PM: 프레스티지 (기존)').replace('msp:prestige','MS Project: 프레스티지 (기존)').replace('pm:prestige','프로젝트 관리: 프레스티지 (기존)')}
async function save(){if(!reason.value.trim()||busy.value)return;busy.value=true;try{await memberRpc('member_admin_detail_save',{p_user:props.user.id,p_answers:answers.value,p_memo:memo.value,p_reason:reason.value});await load();message.value='가입 답변·관리자 메모와 수정 사유를 기록했습니다.'}catch(e){message.value=e.message}finally{busy.value=false}}
function toggleRequest(item,checked){if(checked){if(item.id==='seedling'){requestCodes.value=['seedling'];return}requestCodes.value=requestCodes.value.filter(c=>c!=='seedling');if(['base','ai','msp','pm'].includes(item.kind))requestCodes.value=requestCodes.value.filter(c=>!detail.value.catalog.some(x=>x.id===c&&x.kind===item.kind));requestCodes.value=[...requestCodes.value,item.id]}else requestCodes.value=requestCodes.value.filter(c=>c!==item.id)}
async function saveRequests(){if(busy.value)return;busy.value=true;try{await memberRpc('member_admin_requested_services_save',{p_user:props.user.id,p_codes:requestCodes.value,p_reason:requestReason.value,p_expected_updated_at:detail.value.details_updated_at||null});await load();message.value='신청 서비스를 저장했습니다. 실제 서비스 권한은 변경하지 않았습니다.';emit('updated')}catch(e){message.value=e.message}finally{busy.value=false}}
watch(()=>props.user.id+':'+props.user.services_revision,load,{immediate:true});onUnmounted(()=>{++epoch})
</script><template><div class="member-detail-tools"><p role="status">{{message}}</p><template v-if="detail"><section><h3>활동 정보</h3><dl><dt>가입일(KST)</dt><dd>{{formatMemberDate(detail.activity.joined_at)}}</dd><dt>마지막 로그인(KST)</dt><dd>{{detail.activity.last_sign_in_at?formatMemberDate(detail.activity.last_sign_in_at):'로그인 기록 없음'}}</dd><dt>이북 등록 / 삭제</dt><dd>{{detail.activity.ebook_count}} / {{detail.activity.deleted_ebook_count}}건</dd><dt>활성 그룹</dt><dd>{{detail.activity.group_count}}개</dd></dl></section><section><h3>등급 설정 · 서비스 종류</h3><ul><li v-for="code in detail.services" :key="code">{{serviceName(code)}}</li></ul><p v-if="detail.requested_services.length">신청 서비스: {{detail.requested_services.map(serviceName).join(', ')}}</p><MemberBulkControls :users="[detail.profile]" :current-codes="detail.services" @updated="load();emit('updated')" /></section><section class="requested-service-editor"><h3>신청 서비스 설정</h3><p>신청 내역만 변경합니다. 실제 이용 권한은 등급 설정에서 변경합니다.</p><div class="request-options"><label v-for="item in detail.catalog" :key="item.id"><input type="checkbox" :checked="requestCodes.includes(item.id)" :disabled="busy" @change="toggleRequest(item,$event.target.checked)">{{item.name}}</label></div><label>변경 사유 (선택)<textarea v-model="requestReason" rows="2" maxlength="2000"></textarea></label><button :disabled="busy||user.system_admin" @click="saveRequests">신청 서비스 저장</button></section><section><h3>가입 답변</h3><p v-if="!detail.original_answers">가입 당시 답변 기록이 없습니다. 아래 현재 회원정보와 구분합니다.</p><form @submit.prevent="save"><label v-for="(_,key) in answers" :key="key">{{key}}<textarea v-model="answers[key]" rows="2" maxlength="2000"></textarea></label><details v-if="detail.original_answers"><summary>원래 가입 답변</summary><dl><template v-for="(value,key) in detail.original_answers" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></template></dl></details><label>관리자 메모 (회원 비공개)<textarea v-model="memo" rows="3" maxlength="5000"></textarea></label><label>변경 사유<textarea v-model="reason" rows="2" maxlength="2000" required></textarea></label><button :disabled="busy||!reason.trim()">답변·메모 저장</button></form></section><section><h3>등급·활동 정지·강제 탈퇴 이력</h3><ol><li v-for="(r,i) in detail.management_history" :key="i">{{formatMemberDate(r.created_at)}} · {{r.action}}<p>{{r.details?.reason||'기록된 사유 없음'}}</p><p v-if="r.details?.before">이전 {{r.details.before.status}} → 이후 {{r.details.after?.status}}</p></li></ol></section></template></div></template><style scoped>.member-detail-tools section{border-top:1px solid #dce6ef;padding:18px 0}.member-detail-tools h3{font-size:18px;font-weight:750;margin:0 0 14px}.member-detail-tools dl{display:grid;grid-template-columns:145px minmax(0,1fr);gap:8px;font-size:14px}.member-detail-tools dd{margin:0;overflow-wrap:anywhere}.member-detail-tools dt{font-weight:650}.member-detail-tools label{display:grid;gap:8px;margin:14px 0}.member-detail-tools textarea{width:100%;border:1px solid #b5c5d5;border-radius:6px;padding:10px}.member-detail-tools li{padding:8px 0;overflow-wrap:anywhere}.member-detail-tools p{margin:8px 0}.member-detail-tools button{border:1px solid #a9bfd6;border-radius:6px;padding:10px 14px;background:#edf3fa}</style>

<style scoped>.request-options{display:grid;grid-template-columns:1fr 1fr;gap:5px 10px}.request-options label{display:flex;align-items:center;gap:7px;margin:0;font-size:13px}.request-options input{width:18px;height:18px}</style>
